import unittest

from api import list_events
from db import EventTable
from export import export_all


def table_of(times):
    return EventTable([{"id": i + 1, "created_at": t} for i, t in enumerate(times)])


class Regression(unittest.TestCase):
    def test_no_event_is_exported_twice(self):
        exported = export_all(table_of([100, 101, 102, 102, 102, 103]), page_size=4)
        ids = [r["id"] for r in exported]
        self.assertEqual(len(ids), len(set(ids)))

    def test_a_burst_bigger_than_a_page(self):
        # Five events in one second, read two at a time.
        exported = export_all(table_of([100, 100, 100, 100, 100]), page_size=2)
        self.assertEqual([r["id"] for r in exported], [1, 2, 3, 4, 5])

    def test_pages_are_in_time_order(self):
        exported = export_all(table_of([105, 101, 103, 102, 104]), page_size=2)
        self.assertEqual([r["created_at"] for r in exported], [101, 102, 103, 104, 105])

    def test_the_last_page_says_there_is_no_more(self):
        rows, cursor = list_events(table_of([100, 101, 102]), None, 5)
        self.assertEqual(len(rows), 3)
        self.assertIsNone(cursor)
